input.command:
cd /workspace
rm -f work.duckdb
duckdb work.duckdb -c "
INSTALL spatial; INSTALL httpfs;
LOAD spatial; LOAD httpfs;
SET geometry_always_xy=true;
CREATE TABLE input_raw AS
SELECT row_number() OVER () - 1 as row_id, cod_imovel, municipio, cod_estado, geometry as geom_wkt
FROM read_csv('lists/goias-sample.csv', header=true, all_varchar=true);
SELECT count(*) FROM input_raw;
"

cd /workspace
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE OR REPLACE TABLE input_typed AS
SELECT row_id, cod_imovel, municipio, cod_estado, geom_wkt,
  CASE WHEN cod_imovel IS NOT NULL AND trim(cod_imovel) != '' THEN 'id' ELSE 'geom' END as row_kind,
  CASE WHEN geom_wkt IS NOT NULL AND trim(geom_wkt) != '' THEN ST_GeomFromText(geom_wkt) ELSE NULL END as geom_orig
FROM input_raw;
SELECT row_id, cod_imovel, row_kind, ST_GeometryType(geom_orig) gt FROM input_typed WHERE row_kind='geom';
"

cd /workspace
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
SELECT cod_imovel, count(*) n FROM input_raw WHERE row_kind IS NULL AND cod_imovel IS NOT NULL AND trim(cod_imovel)!='' GROUP BY 1 HAVING count(*)>1;
" 2>&1 | tail -5
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
SELECT cod_imovel, count(*) n FROM input_raw WHERE cod_imovel IS NOT NULL AND trim(cod_imovel)!='' GROUP BY 1 HAVING count(*)>1 ORDER BY n DESC;
"
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
SELECT count(*) total_id_rows, count(distinct cod_imovel) distinct_ids FROM input_raw WHERE cod_imovel IS NOT NULL AND trim(cod_imovel)!='';
"

cd /workspace
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
SELECT cod_imovel FROM input_raw WHERE cod_imovel IN (
  'GO-5212204-15108D4D7C134B8D9E71E50A2ED2E605',
  'GO-5212204-6A28AC5AF7BF4BEC8931E8E154D99AEE',
  'GO-5212204-F17BEA20B17148C1ADB4BD53A04EC448'
);
"

cd /workspace
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs;
CREATE OR REPLACE TABLE car_check AS
SELECT r.cod_imovel, r.origin, (c.cod_imovel IS NOT NULL) as found
FROM resolved_ids r
LEFT JOIN (SELECT DISTINCT cod_imovel FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')) c
  ON r.cod_imovel = c.cod_imovel;
SELECT found, count(*) FROM car_check GROUP BY 1;
SELECT cod_imovel, origin FROM car_check WHERE NOT found;
"

