LOAD spatial; SET geometry_always_xy=true;
SELECT min(ST_XMin(geometry)) xmin, max(ST_XMax(geometry)) xmax, min(ST_YMin(geometry)) ymin, max(ST_YMax(geometry)) ymax
FROM listed_parcels;
