cd /workspace
duckdb work.duckdb -c "
LOAD spatial; SET geometry_always_xy=true;
CREATE OR REPLACE TABLE parcels_buffered AS
SELECT cod_imovel, ST_Transform(geometry,'EPSG:4326','EPSG:5880', true) as geom_m
FROM listed_parcels;
CREATE OR REPLACE TABLE dissolved_union AS
SELECT ST_Transform(ST_Union_Agg(ST_Buffer(geom_m, 25)), 'EPSG:5880','EPSG:4326', true) as geom
FROM parcels_buffered;
SELECT ST_GeometryType(geom), ST_Area(geom) FROM dissolved_union;
"

cd /workspace
time duckdb work.duckdb -c "
LOAD spatial; SET geometry_always_xy=true;
CREATE OR REPLACE TABLE field_union_frac AS
SELECT f.field_id, ST_Area(f.geometry) as field_area,
  ST_Area(ST_Intersection(f.geometry, u.geom)) as inter_union_area
FROM fields_env f, dissolved_union u
WHERE ST_Intersects(f.geometry, u.geom);
SELECT count(*) FROM field_union_frac;
"

