LOAD spatial;
CREATE OR REPLACE TABLE flagged_parcels AS
SELECT DISTINCT primary_cod_imovel as cod_imovel
FROM matched_fields_scoped
WHERE in_scope AND loss2124_ha > 0;
SELECT count(*) FROM flagged_parcels;
"

cd /workspace
duckdb work.duckdb -c "
LOAD spatial;
CREATE OR REPLACE TABLE parcel_class_area AS
SELECT primary_cod_imovel as cod_imovel, mbmode24, sum(field_area_ha) as class_ha
FROM matched_fields_scoped
WHERE primary_cod_imovel IN (SELECT cod_imovel FROM flagged_parcels)
GROUP BY 1,2;
CREATE OR REPLACE TABLE parcel_dominant AS
SELECT cod_imovel, mbmode24 as dominant_mb, class_ha
FROM (
  SELECT *, row_number() OVER (PARTITION BY cod_imovel ORDER BY class_ha DESC, mbmode24 ASC) as rn
  FROM parcel_class_area
) WHERE rn=1;
SELECT pd.cod_imovel, pd.dominant_mb, s.mb_class, s.annex1_commodity, s.in_scope FROM parcel_dominant pd LEFT JOIN scope_table s ON pd.dominant_mb=s.mbmode24 ORDER BY 1;
"

cd /workspace
duckdb work.duckdb -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE OR REPLACE TABLE facilities AS
SELECT entity_id, entity_kind, tier, weight, basis, geom_method, geometry
FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
CREATE OR REPLACE TABLE parcel_centroids AS
SELECT cod_imovel, ST_Centroid(geometry) as centroid, ST_Transform(ST_Centroid(geometry),'EPSG:4326','EPSG:5880', true) as centroid_m
FROM listed_parcels;
SELECT count(*) FROM facilities;
SELECT count(*) FROM parcel_centroids;
"

